</div></section></div></div><!--close column table wrapper. Autoclose: 1 --><div class="flex_column_table av-mij8zxq9-c11a43ab49de8fd636f7dc745f458322 sc-av_one_third av-equal-height-column-flextable"><div class="flex_column av-mij8zxq9-c11a43ab49de8fd636f7dc745f458322 av_one_third avia-builder-el-51 el_after_av_one_third el_before_av_one_third first flex_column_table_cell av-equal-height-column av-align-top shadow-not-animated column-top-margin"><div class="avia-image-container av-mikdafvq-672f10c57c9d71a64b3fbf322ae495af av-styling- avia-align-center avia-builder-el-52 el_before_av_heading avia-builder-el-first" itemprop="image" itemscope="itemscope" itemtype="https://schema.org/ImageObject"><div class="avia-image-container-inner"><div class="avia-image-overlay-wrap"><img alt="neurology" class="wp-image-2346 avia-img-lazy-loading-not-2346 avia_image" decoding="async" fetchpriority="high" height="64" itemprop="thumbnailUrl" sizes="(max-width: 64px) 100vw, 64px" src="../wp-content/uploads/2025/11/neurology.png" srcset="../wp-content/uploads/2025/11/neurology.png 64w, ../wp-content/uploads/2025/11/neurology-36x36.png 36w" title="neurology" width="64"/></div></div></div>
